{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name, count(*) n, round(avg(value),2) avg_v, round(min(value),2) mn, round(max(value),2) mx FROM abnormal_metrics WHERE attr_k8s_pod_name = 'profile-66ffff969-6rk4n' AND metric IN ('k8s.container.ready','k8s.container.restarts') GROUP BY 1,2",
          "claim": "Profile pod is never ready in the abnormal window (ready=0) and its restart count climbs from 2 to 6."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, count(*) n, round(avg(value),2) v FROM abnormal_metrics WHERE metric='k8s.deployment.available' GROUP BY 1,2 UNION ALL SELECT 'norm', metric, count(*), round(avg(value),2) FROM normal_metrics WHERE metric='k8s.deployment.available' GROUP BY 1,2",
          "claim": "Deployment availability is 1 in the normal period and 0 throughout the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name LIKE 'profile.%' OR service_name = 'profile' GROUP BY 1,2,3,4",
          "claim": "No profile server spans appear in the abnormal window; all profile calls are client-side errors from frontend."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE span_name = 'profile.Profile/GetProfiles' GROUP BY 1,2,3,4",
          "claim": "All 856 frontend calls to profile.Profile/GetProfiles return Error in about 0.01 ms, a fast failure."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND attr_http_response_status_code = 500 GROUP BY 1,2",
          "claim": "Frontend user-facing /hotels and /recommendations routes return HTTP 500 for the failed profile calls."
        }
      ]
    }
  ]
}

